from typing import Annotated, Any, Literal, TypedDict

from pydantic import BaseModel, Field

from app.services.retrieval.hybrid_retriever import CorpusChunkRecord, RetrievedChunk


class DocumentCatalogEntry(BaseModel):
    """Lightweight document summary passed to the query planner."""

    document_id: str
    title: str
    page_count: int | None = None
    toc_titles: list[str] = Field(default_factory=list)


class SubQuery(BaseModel):
    """Targeted retrieval sub-query generated by the query decomposer."""

    query: str = Field(..., min_length=1, description="Focused search query for retrieval.")
    target_document_ids: list[str] = Field(
        default_factory=list,
        description="Optional list of specific document_id strings to restrict this sub-query to.",
    )
    page_start: int | None = Field(default=None, ge=1)
    page_end: int | None = Field(default=None, ge=1)


class QueryPlan(BaseModel):
    """Structured query classification and decomposition plan."""

    query_type: Literal[
        "single_fact",
        "multi_hop",
        "cross_document_compare",
        "summary",
        "out_of_scope",
    ] = "single_fact"
    sub_queries: list[SubQuery] = Field(default_factory=list)
    needs_comparison_table: bool = False
    reasoning: str = ""


class RetrievalAssessment(BaseModel):
    """Structured evaluation of retrieved passages against the user query."""

    sufficient: bool
    relevant_chunk_ids: list[str] = Field(
        default_factory=list,
        description="Subset of chroma_id values that directly help answer the query.",
    )
    rewritten_query: str | None = Field(
        default=None,
        description="Alternative query if retrieved evidence is insufficient.",
    )
    reason: str = ""


class ResearchAgentState(TypedDict, total=False):
    """LangGraph state flowing through decomposition, retrieval, grading, synthesis, and guard."""

    query: str
    history_text: str
    document_catalog: list[DocumentCatalogEntry]
    scoped_document_ids: list[str]
    corpus: list[CorpusChunkRecord]

    # Decomposition outputs
    query_type: str
    sub_queries: list[SubQuery]
    needs_comparison_table: bool

    # Retrieval & grading outputs
    retrieved_chunks: list[RetrievedChunk]
    relevant_chunks: list[RetrievedChunk]
    total_retrieved_count: int
    retry_count: int
    needs_retry: bool
    rewritten_query: str | None

    # Synthesis & citation guard outputs
    raw_answer: str
    final_answer: str
    citations: list[dict[str, Any]]
    abstained: bool
    steps: list[str]
    latency_ms: int

